from pathlib import Path
import base64, zlib, hashlib
EXPECTED = '2fac53a77568525781f4945321ca3b21b8c9bb20561d6c1f7db118a6ae8e127d'
DATA = ''
b = zlib.decompress(base64.b64decode(DATA))
h = hashlib.sha256(b).hexdigest()
if h != EXPECTED:
    raise SystemExit(f"V9_HARNESS_SHA_FAIL {h} expected={EXPECTED}")
Path("payload/fullreg_c8b8.c").write_bytes(b)
print("V9_HARNESS_INSTALL_PASS SHA256=" + h)
